module top_module_tb;
    // 测试信号
    reg clk;
    reg rst_n;
    reg [7:0] data_in;
    wire [7:0] data_out;
    wire valid;

    // 实例化顶层模块
    top_module u_top(
        .clk(clk),
        .rst_n(rst_n),
        .data_in(data_in),
        .data_out(data_out),
        .valid(valid)
    );

    // 时钟生成
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // 测试激励
    initial begin
        // 初始化
        rst_n = 0;
        data_in = 8'b0;
        #20;

        // 释放复位
        rst_n = 1;
        #10;

        // 测试数据
        data_in = 8'h5A;
        #20;
        data_in = 8'h00;

        // 等待处理完成
        #50;

        // 结束仿真
        $finish;
    end

    // 波形监视
    initial begin
        $monitor("Time=%0t rst_n=%b data_in=%h data_out=%h valid=%b",
                $time, rst_n, data_in, data_out, valid);
    end

endmodule

